def rle(text: str) -> str:
    """Run-length encode: each run as length+char, length omitted when 1.

    Raises ValueError if the input contains any digit, because digits in the
    input cannot be unambiguously represented in the encoded format.
    """
    if any(ch.isdigit() for ch in text):
        raise ValueError("text contains digits, cannot run-length encode unambiguously")
    if not text:
        return ""
    result = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{count}{prev}" if count > 1 else prev)
            prev = ch
            count = 1
    result.append(f"{count}{prev}" if count > 1 else prev)
    return "".join(result)


def unrle(code: str) -> str:
    """Inverse of rle: '3ab2c' -> 'aaabcc', '12a' -> twelve 'a's.

    Raises ValueError on malformed input: a count with no character after it,
    or a count of 0.
    """
    result = []
    i = 0
    while i < len(code):
        if code[i].isdigit():
            j = i
            while j < len(code) and code[j].isdigit():
                j += 1
            count = int(code[i:j])
            if count == 0:
                raise ValueError("run length must be positive")
            if j >= len(code):
                raise ValueError("missing character after run length")
            result.append(code[j] * count)
            i = j + 1
        else:
            result.append(code[i])
            i += 1
    return "".join(result)
```

This final version:
- `rle` rejects any input containing digits.
- `unrle` rejects run lengths of `0` and counts that are not followed by a character.
- The round-trip `unrle(rle(s)) == s` holds for all digit‑free strings.

