def format_table(rows):
    if not rows:
        return ""
    n_cols = len(rows[0])
    widths = [0] * n_cols
    for row in rows:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(str(cell)))

    lines = []
    for row in rows:
        cells = []
        for i, cell in enumerate(row):
            s = str(cell)
            is_number = isinstance(cell, (int, float)) and not isinstance(cell, bool)
            if i == n_cols - 1:
                # Last column: no trailing spaces needed
                cells.append(s.rjust(widths[i]) if is_number else s)
            else:
                cells.append(s.rjust(widths[i]) if is_number else s.ljust(widths[i]))
        lines.append(" | ".join(cells))

    longest = max(len(line) for line in lines)
    separator = "-" * longest
    lines.insert(1, separator)

    return "\n".join(lines)
