def spiral(matrix, counterclockwise=False):
    """
    Return the elements of a 2-D list (list of rows) in spiral order.

    Default is clockwise, starting at the top-left corner and moving right.
    If counterclockwise=True, start at the top-left corner and move down first.

    Raises ValueError if rows have different lengths.
    Returns an empty list for an empty matrix or if all rows are empty.
    """
    # Handle empty input
    if not matrix:
        return []

    # Check that rows are not all empty
    non_empty_row_length = None
    for row in matrix:
        if row:  # non-empty row
            non_empty_row_length = len(row)
            break

    if non_empty_row_length is None:
        # all rows are empty
        return []

    # Validate consistent row lengths
    for i, row in enumerate(matrix):
        if len(row) != non_empty_row_length:
            raise ValueError(f"Row {i} has length {len(row)}, expected {non_empty_row_length}")

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, non_empty_row_length - 1

    if not counterclockwise:
        # Clockwise: right → down → left → up
        while top <= bottom and left <= right:
            for col in range(left, right + 1):
                result.append(matrix[top][col])
            top += 1

            for row in range(top, bottom + 1):
                result.append(matrix[row][right])
            right -= 1

            if top <= bottom:
                for col in range(right, left - 1, -1):
                    result.append(matrix[bottom][col])
                bottom -= 1

            if left <= right:
                for row in range(bottom, top - 1, -1):
                    result.append(matrix[row][left])
                left += 1
    else:
        # Counter‑clockwise: down → right → up → left
        while top <= bottom and left <= right:
            for row in range(top, bottom + 1):
                result.append(matrix[row][left])
            left += 1

            if top <= bottom:
                for col in range(left, right + 1):
                    result.append(matrix[bottom][col])
                bottom -= 1

            if left <= right:
                for row in range(bottom, top - 1, -1):
                    result.append(matrix[row][right])
                right -= 1

            if top <= bottom:
                for col in range(right, left - 1, -1):
                    result.append(matrix[top][col])
                top += 1

    return result
