from urllib.parse import unquote_plus

def parse_query(qs):
    """
    Parse a URL query string into a dict.

    - A leading '?' is allowed and ignored.
    - Keys and values are percent-decoded; '+' means a space.
    - A key without '=' gets an empty string value.
    - Empty pieces (e.g., between '&&') are skipped.
    - If a key appears once, its value is a plain string.
    - If a key appears more than once, its value is a list of all
      values in the order they appeared.
    """
    if qs and qs.startswith('?'):
        qs = qs[1:]
    if not qs:
        return {}

    collected = {}
    for item in qs.split('&'):
        if not item:
            continue
        if '=' in item:
            key, value = item.split('=', 1)
        else:
            key, value = item, ''
        key = unquote_plus(key)
        value = unquote_plus(value)
        collected.setdefault(key, []).append(value)

    result = {}
    for key, values in collected.items():
        result[key] = values[0] if len(values) == 1 else values
    return result
```

