def get_path(data, path, default=None):
    """
    Read a value from nested dicts/lists using a dotted path.

    Args:
        data: The (possibly nested) structure to read from.
        path: A string like "a.b.c", "users.0.name", "items.-1",
              or "" (empty returns data itself).
        default: Value returned if any part of the path cannot be resolved.

    Returns:
        The value at the given path, or `default` if the path is invalid.
    """
    if not path:
        return data

    current = data
    try:
        for part in path.split("."):
            if isinstance(current, dict):
                if part not in current:
                    raise KeyError(part)
                current = current[part]
            elif isinstance(current, list):
                try:
                    idx = int(part)      # handles negative indices
                except ValueError:
                    raise KeyError(part) # not an integer
                try:
                    current = current[idx]
                except IndexError:
                    raise KeyError(part) # out of range
            else:
                raise KeyError(part)     # cannot traverse a scalar
        return current
    except KeyError:
        return default
