import re


def tokenize(expression: str):
    """Convert an expression string into a list of tokens."""
    tokens = []
    pos = 0
    length = len(expression)

    while pos < length:
        char = expression[pos]

        if char.isspace():
            pos += 1
            continue

        if char in "+-*/()":
            tokens.append((char, char))
            pos += 1
            continue

        match = re.match(r"(?:\d+(?:\.\d*)?|\.\d+)", expression[pos:])
        if match:
            tokens.append(("NUM", match.group()))
            pos += match.end()
            continue

        raise ValueError(f"Malformed expression: unexpected character {char!r}")

    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        token = self.peek()
        if token is not None:
            self.pos += 1
        return token

    def parse(self):
        if self.peek() is None:
            raise ValueError("Malformed expression: empty input")
        value = self.expression()
        if self.peek() is not None:
            raise ValueError("Malformed expression: unexpected trailing tokens")
        return value

    def expression(self):
        value = self.term()
        while True:
            token = self.peek()
            if token is None or token[0] not in "+-":
                break
            self.advance()
            right = self.term()
            value = value + right if token[0] == "+" else value - right
        return value

    def term(self):
        value = self.factor()
        while True:
            token = self.peek()
            if token is None or token[0] not in "*/":
                break
            self.advance()
            right = self.factor()
            if token[0] == "*":
                value = value * right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                value = value / right
        return value

    def factor(self):
        token = self.peek()
        if token is None:
            raise ValueError("Malformed expression: expected a number or '('")

        kind, text = token

        if kind == "NUM":
            self.advance()
            return float(text)

        if text == "(":
            self.advance()
            value = self.expression()
            if self.peek() is None or self.peek()[0] != ")":
                raise ValueError("Malformed expression: missing ')'")
            self.advance()
            return value

        if text in "+-":
            self.advance()
            value = self.factor()
            return -value if text == "-" else value

        raise ValueError("Malformed expression: unexpected token")


def evaluate(expression: str):
    """Evaluate a mathematical expression.

    Supports +, -, *, /, parentheses, unary +/- and decimal numbers.
    Raises ValueError for division by zero or malformed expressions.
    """
    result = _Parser(tokenize(expression)).parse()
    if isinstance(result, float) and result.is_integer():
        return int(result)
