def final_grade(scores, weights=None):
    """Return (average rounded to 1 decimal, letter grade).

    - Validates: scores must be a non-empty dict, each score between 0 and 100.
    - Weighted average: weights dict maps names to weights, missing names get weight 1.
    - Drops the single lowest score when there are at least 4 scores.
    - Letter: A>=90, B>=80, C>=70, D>=60, F<60 (based on rounded average).
    """
    if not scores:
        raise ValueError("scores dict must not be empty")

    for name, score in scores.items():
        if not (0 <= score <= 100):
            raise ValueError(f"Score for '{name}' is out of range: {score}")

    if weights is None:
        weights = {}

    items = list(scores.items())

    # Drop the lowest score if we have at least 4 scores
    if len(items) >= 4:
        min_score = min(score for _, score in items)
        for i, (_, score) in enumerate(items):
            if score == min_score:
                del items[i]
                break

    total_weight = 0.0
    weighted_sum = 0.0
    for name, score in items:
        w = weights.get(name, 1)
        weighted_sum += score * w
        total_weight += w

    if total_weight == 0:
        raise ValueError("Total weight cannot be zero")

    avg = weighted_sum / total_weight
    rounded = round(avg, 1)

    if rounded >= 90:
        letter = 'A'
    elif rounded >= 80:
        letter = 'B'
    elif rounded >= 70:
        letter = 'C'
    elif rounded >= 60:
        letter = 'D'
    else:
        letter = 'F'

    return (rounded, letter)
