def flatten(obj, depth=None):
    """
    Flatten nested lists and tuples into a flat list, ignoring strings/bytes.
    Dictionaries and sets are kept whole as single items.
    If obj is not a list or tuple, return [obj].

    depth: maximum number of nesting levels to flatten.
           depth=None means no limit (flatten fully).
           depth=0 returns a shallow copy of the top-level as a list.
    """
    if not isinstance(obj, (list, tuple)):
        return [obj]

    result = []
    for item in obj:
        if isinstance(item, (list, tuple)) and (depth is None or depth > 0):
            if depth is None:
                result.extend(flatten(item))
            else:
                result.extend(flatten(item, depth - 1))
        else:
            result.append(item)
    return result
