from urllib.parse import unquote_plus

def parse_query(qs):
    """Parse a URL query string into a dict of strings or lists.

    - A leading '?' is allowed and ignored.
    - Pieces are split on '&'; empty pieces are skipped.
    - A piece with no '=' is a key whose value is the empty string.
    - Keys and values are percent-decoded; '+' means a space.
    - A key appearing once maps to a plain string; a key appearing
      multiple times maps to a list of its values in order.
    """
    result = {}
    if not qs:
        return result

    if qs.startswith("?"):
        qs = qs[1:]

    for pair in qs.split("&"):
        if not pair:
            continue
        if "=" in pair:
            key, value = pair.split("=", 1)
        else:
            key, value = pair, ""
        key = unquote_plus(key)
        value = unquote_plus(value)

        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    return result
```

Example usage:

```python
>>> parse_query("a=1&b=2")
{'a': '1', 'b': '2'}

>>> parse_query("?a=1&b=2")
{'a': '1', 'b': '2'}

>>> parse_query("?a=1&a=2&a=3&b=4")
{'a': ['1', '2', '3'], 'b': '4'}

>>> parse_query("a=1&&b=2")
{'a': '1', 'b': '2'}

>>> parse_query("flag")
{'flag': ''}

>>> parse_query("?x=100%25&name=Ada+Lovelace")
{'x': '100%', 'name': 'Ada Lovelace'}

>>> parse_query("")
{}
```

All the requested behaviors are covered: optional leading `?` is stripped, empty pieces are skipped, pieces without `=` yield an empty-string value, keys/values are percent-decoded with `+` as a space, and repeated keys collect their values into an ordered list while single occurrences stay plain strings.

