def balanced(text):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set('([{')
    quote_char = None   # None, "'", or '"'
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        # A backslash escapes the next character, so skip both.
        if ch == '\\':
            i += 2
            continue

        if quote_char is not None:
            # Inside a string: only a matching quote ends it.
            if ch == quote_char:
                quote_char = None
            i += 1
            continue

        # Not inside a string.
        if ch in "'\"":
            quote_char = ch
        elif ch in openers:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        i += 1

    # Unclosed string means unbalanced.
    if quote_char is not None:
        return False
    return not stack
