        key = key.strip()
        if section:
            key = section + '.' + key

        value = value.strip()
        lower = value.lower()
        if lower == 'true':
            value = True
        elif lower == 'false':
            value = False
        else:
            try:
                value = int(value)
            except ValueError:
                pass  # keep as string

        result[key] = value
    return result
