def final_grade(scores, weights=None):
    """Return (average rounded to 1 decimal, letter grade).

    scores: dict mapping assignment names to scores (0-100).
    weights: optional dict mapping names to weights; missing names get weight 1.
    The single lowest raw score is dropped when there are at least 4 scores.
    Raises ValueError if scores is empty or any score is outside 0-100.
    Letter grades: A>=90, B>=80, C>=70, D>=60, else F (based on the rounded average).
    """
    if not scores:
        raise ValueError("scores dict cannot be empty")

    for name, score in scores.items():
        if not (0 <= score <= 100):
            raise ValueError(f"Score for '{name}' must be between 0 and 100, got {score}")

    if weights is None:
        weights = {}

    # Drop the lowest score if at least 4 assignments
    if len(scores) >= 4:
        lowest_name = min(scores, key=scores.get)
        scores = {name: score for name, score in scores.items() if name != lowest_name}

    total = 0.0
    weight_sum = 0.0
    for name, score in scores.items():
        w = weights.get(name, 1)
        total += score * w
        weight_sum += w

    if weight_sum == 0:
        avg = 0.0
    else:
        avg = total / weight_sum

    avg_rounded = round(avg, 1)

    if avg_rounded >= 90:
        letter = 'A'
    elif avg_rounded >= 80:
        letter = 'B'
    elif avg_rounded >= 70:
        letter = 'C'
    elif avg_rounded >= 60:
        letter = 'D'
    else:
        letter = 'F'

    return (avg_rounded, letter)
