import re

def parse_duration(text: str) -> int:
    """
    Parse a duration string and return the total number of seconds as an int.

    Supported units (case-insensitive):
        d = days, h = hours, m = minutes, s = seconds
    Components may appear in any order and be separated by spaces.
    A bare number (no unit) is interpreted as minutes.

    Raises ValueError if the text is empty, contains only whitespace,
    or has any part that cannot be parsed.
    """
    if not isinstance(text, str):
        raise TypeError(f"Expected str, got {type(text).__name__}")

    # Match each component: digits optionally followed by a unit letter.
    pattern = re.compile(r"\d+\s*[dhms]?", re.IGNORECASE)
    matches = list(pattern.finditer(text))
    if not matches:
        raise ValueError(f"Not a valid duration: {text!r}")

    # Ensure every non-space character is covered by a match.
    covered = set()
    for m in matches:
        covered.update(range(m.start(), m.end()))
    for i, ch in enumerate(text):
        if ch != " " and i not in covered:
            raise ValueError(f"Not a valid duration: {text!r}")

    unit_map = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    total = 0

    for m in matches:
        token = m.group(0).replace(" ", "").lower()
        if not token:
            continue
        # If the token ends with a known unit, split; otherwise it's bare minutes.
        if token[-1] in unit_map:
            num_part, unit = token[:-1], token[-1]
        else:
            num_part, unit = token, "m"  # bare number → minutes
        if not num_part:
            raise ValueError(f"Not a valid duration: {text!r}")
        total += int(num_part) * unit_map[unit]

    return int(total)
