def format_table(rows):
    """Return a plain-text table from a list of rows.

    The first row is a header; a line of '-' characters is placed beneath it,
    as long as the longest line of the table. No other separator lines are used.

    Cells are converted with str(). Numbers (int/float, but not bool) are
    right-aligned in their column; everything else is left-aligned. Columns are
    padded to the width of their widest cell. No line ends with a space, the
    result has no trailing newline, and an empty list of rows yields "".
    """
    if not rows:
        return ""

    # Keep originals for type detection; also stringify everything.
    orig = [list(r) for r in rows]
    strs = [[str(c) for c in r] for r in orig]
    ncols = max(len(r) for r in strs)

    # Column widths = max string length in each column.
    widths = [0] * ncols
    for col in range(ncols):
        for r in strs:
            if col < len(r):
                widths[col] = max(widths[col], len(r[col]))

    def is_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    lines = []
    for o_row, s_row in zip(orig, strs):
        parts = []
        for col in range(ncols):
            if col < len(s_row):
                text = s_row[col]
                if is_number(o_row[col]):
                    parts.append(text.rjust(widths[col]))
                else:
                    parts.append(text.ljust(widths[col]))
            else:
                parts.append(" " * widths[col])
        lines.append(" | ".join(parts).rstrip())

    # Header separator: '-' as long as the longest line, inserted under the header.
    sep = "-" * max(len(line) for line in lines)
    lines.insert(1, sep)

    return "\n".join(lines)
