def spiral(matrix, counterclockwise=False):
    if not matrix or not matrix[0]:
        return []

    # Check that all rows have the same length
    row_len = len(matrix[0])
    for row in matrix:
        if len(row) != row_len:
            raise ValueError("All rows must have the same length")

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    if not counterclockwise:
        # Clockwise spiral
        while top <= bottom and left <= right:
            # Traverse right along the top row
            for col in range(left, right + 1):
                result.append(matrix[top][col])
            top += 1

            # Traverse down along the right column
            for row in range(top, bottom + 1):
                result.append(matrix[row][right])
            right -= 1

            # Traverse left along the bottom row (if any rows remain)
            if top <= bottom:
                for col in range(right, left - 1, -1):
                    result.append(matrix[bottom][col])
                bottom -= 1

            # Traverse up along the left column (if any columns remain)
            if left <= right:
                for row in range(bottom, top - 1, -1):
                    result.append(matrix[row][left])
                left += 1
    else:
        # Counterclockwise spiral
        while top <= bottom and left <= right:
            # Traverse down along the left column
            for row in range(top, bottom + 1):
                result.append(matrix[row][left])
            left += 1

            # Traverse right along the bottom row (if any rows remain)
            if top <= bottom:
                for col in range(left, right + 1):
                    result.append(matrix[bottom][col])
                bottom -= 1

            # Traverse up along the right column (if any columns remain)
            if left <= right:
                for row in range(bottom, top - 1, -1):
                    result.append(matrix[row][right])
                right -= 1

            # Traverse left along the top row (if any rows remain)
            if top <= bottom:
                for col in range(right, left - 1, -1):
                    result.append(matrix[top][col])
                top += 1

    return result
