def parse_query(qs: str) -> dict[str, str | list[str]]:
    """Parse a URL query string into a dict.

    Rules:
    - A leading '?' is allowed and ignored.
    - Keys and values are percent-decoded; '+' means a space.
    - A piece with no '=' is a key whose value is the empty string.
    - Empty pieces, as in "a=1&&b=2", are skipped.
    - A key appearing once -> plain string value.
    - A key appearing multiple times -> list of its values, in order.

    Examples:
        >>> parse_query("a=1&b=2")
        {'a': '1', 'b': '2'}
        >>> parse_query("?a=1&b=2")
        {'a': '1', 'b': '2'}
        >>> parse_query("name=John+Doe&q=100%25")
        {'name': 'John Doe', 'q': '100%'}
        >>> parse_query("a=1&&b=2")
        {'a': '1', 'b': '2'}
        >>> parse_query("a=1&a=2&b=3")
        {'a': ['1', '2'], 'b': '3'}
        >>> parse_query("flag&x=1")
        {'flag': '', 'x': '1'}
        >>> parse_query("?")
        {}
    """
    if qs.startswith("?"):
        qs = qs[1:]

    groups: dict[str, list[str]] = {}
    if not qs:
        return {}

    for pair in qs.split("&"):
        if not pair:  # skip empty pieces, e.g. "a=1&&b=2"
            continue
        if "=" in pair:
            key, _, value = pair.partition("=")
            key = unquote_plus(key)
            value = unquote_plus(value)
        else:
            key = unquote_plus(pair)
            value = ""

        groups.setdefault(key, []).append(value)

    # Collapse single-element lists to plain strings.
    return {k: v[0] if len(v) == 1 else v for k, v in groups.items()}
