import math

def summary(values):
    def is_nan(x):
        try:
            return math.isnan(x)
        except TypeError:
            return False

    # Skip None and NaN values
    vals = [v for v in values if v is not None and not is_nan(v)]

    if not vals:
        raise ValueError("summary() requires at least one non-None, non-NaN value")

    n = len(vals)
    mean = round(sum(vals) / n, 2)

    sorted_vals = sorted(vals)
    mid = n // 2
    if n % 2 == 0:
        median = round((sorted_vals[mid - 1] + sorted_vals[mid]) / 2, 2)
    else:
        median = round(sorted_vals[mid], 2)

    counts = {}
    for v in vals:
        counts[v] = counts.get(v, 0) + 1
    max_count = max(counts.values())
    mode = round(min(v for v, c in counts.items() if c == max_count), 2)

    return {"mean": mean, "median": median, "mode": mode}
