def unrle(code):
    """Run-length decode: "3ab2c" -> "aaabcc".

    Raises ValueError on malformed input:
    - a count with no character after it (e.g. "12" or "3a2")
    - a count of zero (e.g. "0a")
    """
    if not code:
        return ""

    result = []
    i = 0
    n = len(code)

    while i < n:
        start = i
        while i < n and code[i].isdigit():
            i += 1

        if i == start:
            # no digits → single character
            result.append(code[i])
            i += 1
        else:
