def format_table(rows):
    """
    Convert a list of rows (each a list of values) into a plain-text table.

    The first row is a header, with a line of '-' characters directly beneath it.
    Columns are padded to the width of their widest cell. Numbers (int/float,
    but not bool) are right-aligned; all other values are left-aligned.
    Cells are separated by " | ". No line ends with a space and the result
    has no trailing newline. An empty list of rows yields an empty string.
    """
    if not rows:
        return ""

    # Convert each cell to (string, is_number) so we know how to align it.
    converted = []
    for row in rows:
        converted_row = []
        for cell in row:
            is_number = isinstance(cell, (int, float)) and not isinstance(cell, bool)
            converted_row.append((str(cell), is_number))
        converted.append(converted_row)

    # Make all rows have the same number of columns (missing cells become empty strings).
    n_cols = max(len(row) for row in converted)
    for row in converted:
        while len(row) < n_cols:
            row.append(("", False))

    # Compute the width of each column (longest cell in that column).
    widths = [0] * n_cols
    for row in converted:
        for i, (text, _) in enumerate(row):
            widths[i] = max(widths[i], len(text))

    # Build each table line, applying alignment and removing trailing spaces.
    lines = []
    for row in converted:
        parts = []
        for i, (text, is_number) in enumerate(row):
            if is_number:
                parts.append(text.rjust(widths[i]))
            else:
                parts.append(text.ljust(widths[i]))
        lines.append(" | ".join(parts).rstrip())

    # The separator is as long as the longest line of the table.
    max_len = max(len(line) for line in lines)
    separator = '-' * max_len

    header = lines[0]
    data_lines = lines[1:]

    if data_lines:
        return header + "\n" + separator + "\n" + "\n".join(data_lines)
    else:
        return header + "\n" + separator
