from urllib.parse import parse_qsl


def parse_query(qs):
    """Parse a URL query string into a dict.

    - A leading '?' is allowed and ignored.
    - Keys and values are percent-decoded; '+' means a space.
    - A piece with no '=' becomes a key with an empty string value.
    - Empty pieces (e.g. between '&&') are skipped.
    - When a key appears more than once, its value becomes a list of
      all its values in order; a single occurrence stays a plain string.

    Examples:
        >>> parse_query("a=1&b=2")
        {'a': '1', 'b': '2'}
        >>> parse_query("?a=1&b=2")
        {'a': '1', 'b': '2'}
        >>> parse_query("a&b=2")
        {'a': '', 'b': '2'}
        >>> parse_query("name=John+Doe&city=New%20York")
        {'name': 'John Doe', 'city': 'New York'}
        >>> parse_query("a=1&a=2&b=3")
        {'a': ['1', '2'], 'b': '3'}
        >>> parse_query("a=1&&b=2")
        {'a': '1', 'b': '2'}
        >>> parse_query("")
        {}
    """
    if not qs:
        return {}
    if qs.startswith('?'):
        qs = qs[1:]

    # parse_qsl skips empty segments and decodes keys/values properly.
    pairs = parse_qsl(qs)
    result = {}
    for key, value in pairs:
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(value)
            else:
                result[key] = [existing, value]
        else:
            result[key] = value
    return result
