def balanced(text: str) -> bool:
    """Return True if brackets are balanced, ignoring brackets inside strings
    and escaped characters (backslash escapes the next character).
    An unclosed quote makes the text unbalanced."""
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    in_string = False
    quote_char = None
    i = 0

    while i < len(text):
        ch = text[i]

        if in_string:
            # Inside a string, backslash escapes the next character
            if ch == '\\' and i + 1 < len(text):
                i += 2          # skip escaped character
                continue
            if ch == quote_char:
                in_string = False
                quote_char = None
        else:
            # Outside a string, backslash escapes the next character
            if ch == '\\' and i + 1 < len(text):
                i += 2          # skip escaped character
                continue
            if ch == "'" or ch == '"':
                in_string = True
                quote_char = ch
            elif ch in "([{":
                stack.append(ch)
            elif ch in ")]}":
                if not stack or stack.pop() != pairs[ch]:
                    return False

        i += 1

    return not stack and not in_string
