def calc(expr):
    """Evaluate an arithmetic expression string with +, -, *, /, parentheses.
    Supports unary +/-, decimals. Returns int when the result is a whole number,
    float otherwise. Raises ValueError for malformed input or division by zero."""
    # Tokenize
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in "+-*/()":
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            num = expr[i:j]
            if num.count('.') > 1 or num == '.':
                raise ValueError(f"Invalid number: {num!r}")
            tokens.append(('num', float(num)))
            i = j
        else:
            raise ValueError(f"Unexpected character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    # Recursive‑descent parser
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expression():
        value = parse_term()
        while True:
            tok = peek()
            if tok in ('+', '-'):
                advance()
                rhs = parse_term()
                value = value + rhs if tok == '+' else value - rhs
            else:
                break
        return value

    def parse_term():
        value = parse_factor()
        while True:
            tok = peek()
            if tok in ('*', '/'):
                advance()
                rhs = parse_factor()
                if tok == '*':
                    value *= rhs
                else:
                    if rhs == 0:
                        raise ValueError("Division by zero")
                    value /= rhs
            else:
                break
        return value

    def parse_factor():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok == '(':
            advance()
            value = parse_expression()
            if peek() != ')':
                raise ValueError("Mismatched parentheses")
            advance()
            return value
        if tok in ('+', '-'):      # unary plus/minus
            advance()
            v = parse_factor()
            return v if tok == '+' else -v
        if isinstance(tok, tuple) and tok[0] == 'num':
            advance()
            return tok[1]
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_expression()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing characters")

    # Return int when whole number, else float
    if isinstance(result, float) and result.is_integer():
        return int(result)
    return result
