def ranges(nums):
    """Return a compact string of ranges from a list of integers.

    The list may be unsorted and may contain duplicates. Only runs of
    three or more consecutive integers are written as "start..end";
    shorter runs are written as individual numbers. Items are separated
    by commas with no spaces. An empty list produces an empty string.

    Examples:
        ranges([])                -> ""
        ranges([1,2])             -> "1,2"
        ranges([1,2,3,5])         -> "1..3,5"
        ranges([5,1,2,5,8,9,10])  -> "1..3,5,8..10"
    """
    if not nums:
        return ""

    nums = sorted(set(nums))
    parts = []
    run = [nums[0]]

    for n in nums[1:]:
        if n == run[-1] + 1:
            run.append(n)
        else:
            _flush_run(run, parts)
            run = [n]

    _flush_run(run, parts)
    return ",".join(parts)


def _flush_run(run, parts):
    """Append a run to parts, using the range rule (only 3+ becomes a range)."""
    if len(run) >= 3:
        parts.append(f"{run[0]}..{run[-1]}")
    else:
        parts.extend(str(x) for x in run)
